+export function createAutonomyPolicy(input: Partial<AutonomyPolicy> & Pick<AutonomyPolicy, "workspace">): AutonomyPolicy {
+  const p: AutonomyPolicy = {
+    workspace: resolve(input.workspace), tools: [...(input.tools ?? [])],
